<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Grid, List, TrendCharts, Document, Setting, Cpu, ArrowDown, ArrowRight, Fold, Select, Operation, DataAnalysis } from '@element-plus/icons-vue'
import GameIcon from './components/GameIcon.vue'
import ReportCard from './components/ReportCard.vue'
import ResearchWorkspace from './components/ResearchWorkspace.vue'
import { createSelection, getProduct, getProducts, getRankings, getSelections, getAiConfig, saveAiConfig, getLatestReport, getReport, getReportHistory, getReportSkill, getInsightCollection, runInsightCollection, generateReport, getCurrentRule, getCoverage, publishRule, getStats, getPublicRankings, type Product, type Ranking } from './api'
const active=ref('overview'),collapsed=ref(false),loading=ref(false),error=ref('')
const groups=reactive<Record<string,boolean>>({'实际使用':true,'配置管理':true})
const filters=reactive({q:'',platform:'',region:'',poolState:'',selectionState:'',date:'',page:1})
const data=ref<any>({date:'',total:0,items:[]}),stats=ref<any>({}),coverage=ref<any>({charts:[]})
const charts=ref<any[]>([]),selectedChart=ref(''),chartPlatform=ref(''),chartType=ref(''),rankingData=ref<any>({items:[]}),selectionData=ref<any>({items:[]})
const reportData=ref<any>({items:[],message:'尚未生成周报'}),reportGroup=ref('ALL')
const reportHistory=ref<any>({items:[],total:0}),historyPage=ref(1),historyOpen=ref(false),reportId=ref(''),generating=ref(false)
const skillOpen=ref(false),skillData=ref<any>(null),collectionStatus=ref<any>(null),collecting=ref(false),auditPage=ref(1)
const reportCoverage=computed(()=>{try{return typeof reportData.value.coverage==='string'?JSON.parse(reportData.value.coverage):reportData.value.coverage||{}}catch{return {}}})
const generatedTime=computed(()=>{const raw=reportData.value.generatedAt;if(!raw)return '—';const value=String(raw);return new Date(value+(value.endsWith('Z')?'':'Z')).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})+'（北京时间）'})
const auditRows=computed(()=>(reportData.value.candidateAudit||[]).slice((auditPage.value-1)*20,auditPage.value*20))
const decisionLabel:Record<string,string>={SELECTED:'入选',LIMIT_OR_DIVERSITY:'限额 / 多样性',DUPLICATE_PRODUCT:'同产品去重',GAMEPLAY_UNVERIFIED:'玩法未核验',COMPLEX_GAMEPLAY_REVIEW:'复杂玩法需核验',INSUFFICIENT_SIGNAL:'市场信号不足',ALREADY_PRODUCING:'制作中 / 已完成',MANUALLY_EXCLUDED:'人工排除'}
const aiConfig=reactive({providerName:'',baseUrl:'',model:'',apiKey:'',apiKeyConfigured:false,timeoutSeconds:60,temperature:0.2,enabled:false})
const ruleData=reactive({versionNumber:0,rulesJson:'{}',status:'NONE',publishedAt:''})
const drawer=ref(false),detail=ref<any>(null),selectionOpen=ref(false),selectionProduct=ref<Product|null>(null)
const form=reactive({owner:'',status:'SELECTED',referenceVersionId:undefined as string|undefined,selectedOn:'',startedOn:'',finishedOn:'',note:''})
const researchModes=['opinions','families','catalog','research','materials','planning','experiments']
const menus=[{group:'实际使用',icon:Grid,items:[{id:'overview',name:'市场概览',icon:DataAnalysis},{id:'products',name:'产品情报库',icon:List},{id:'rankings',name:'榜单观察',icon:TrendCharts},{id:'opinions',name:'玩家评价与舆情',icon:Document},{id:'families',name:'玩法与赛道',icon:Grid},{id:'reports',name:'每周精选',icon:Document},{id:'selections',name:'选用与测试记录',icon:Select},{id:'experiments',name:'验证反馈',icon:Select}]},{group:'配置管理',icon:Setting,items:[{id:'catalog',name:'信息采集范围',icon:List},{id:'research',name:'研究目标与推荐',icon:Operation},{id:'materials',name:'研究材料与补证',icon:Document},{id:'collection',name:'AI采集中心',icon:Cpu},{id:'planning',name:'采集接入规划',icon:Setting}]}]
const title=computed(()=>menus.flatMap(m=>m.items).find(m=>m.id===active.value)?.name||'产品库')
const platformLabel:Record<string,string>={WECHAT:'微信',DOUYIN:'抖音',IOS:'iOS',GOOGLE_PLAY:'Google Play'}
const regionLabel:Record<string,string>={CN:'中国',US:'美国',GB:'英国',DE:'德国',FR:'法国'}
const stateLabel:Record<string,string>={FORMAL:'正式库',OBSERVING:'观察中',PENDING_IDENTIFICATION:'待识别',EXCLUDED:'已排除',MISSING_SNAPSHOT:'当日缺失',NOT_IN_COVERAGE:'未在覆盖内',PARTIAL_COVERAGE:'覆盖不全',OBSERVED:'已观察'}
const versionChoices=computed(()=>[...new Map(selectionProduct.value?.rankings.map(r=>[r.versionId,r])||[]).values()])
const currentChart=computed(()=>charts.value.find(c=>String(c.id)===selectedChart.value))
const availableCharts=computed(()=>charts.value.filter(c=>(!chartPlatform.value||c.platform===chartPlatform.value)&&(!chartType.value||c.chart_type===chartType.value)))
const publicData=ref<Record<string,any>>({})
const visibleReports=computed(()=>reportData.value.items.filter((r:any)=>reportGroup.value==='ALL'||(reportGroup.value==='DOMESTIC'?facts(r).region==='CN':facts(r).platform==='GOOGLE_PLAY')))
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date())
const disabledDate=(d:Date)=>d>new Date(`${today()}T23:59:59`)
let loadVersion=0
async function load(){const token=++loadVersion;loading.value=true;error.value='';try{
 if(!filters.date){coverage.value=await getCoverage('');filters.date=coverage.value.date}
 const day=filters.date
 if(active.value==='overview'){const [stat,cov]=await Promise.all([getStats(day),getCoverage(day)]);if(token!==loadVersion)return;stats.value=stat;coverage.value=cov}
 else if(active.value==='products'){const [products,stat,cov]=await Promise.all([getProducts({...filters,pageSize:20}),getStats(day),getCoverage(day)]);if(token!==loadVersion)return;data.value=products;stats.value=stat;coverage.value=cov}
 else if(active.value==='rankings'){const [cov,wx,dy]=await Promise.all([getCoverage(day),getPublicRankings('WECHAT',day),getPublicRankings('DOUYIN',day)]);if(token!==loadVersion)return;coverage.value=cov;publicData.value={WECHAT:wx,DOUYIN:dy};charts.value=[{id:'public-WECHAT',platform:'WECHAT',region:'CN',name:'微信小游戏人气榜',chart_type:'POPULARITY',public:true,data_state:wx.completeness,actual_count:wx.items.length},{id:'public-DOUYIN',platform:'DOUYIN',region:'CN',name:'抖音小游戏热门榜',chart_type:'POPULARITY',public:true,data_state:dy.completeness,actual_count:dy.items.length},...cov.charts.slice().sort((a:any,b:any)=>(a.platform==='IOS'?0:1)-(b.platform==='IOS'?0:1)||['CN','US','GB','DE','FR'].indexOf(a.region)-['CN','US','GB','DE','FR'].indexOf(b.region))];if(!availableCharts.value.some(c=>String(c.id)===selectedChart.value))selectedChart.value=String(availableCharts.value[0]?.id||'');await loadChart()}
 else if(active.value==='reports'){const report=reportId.value?await getReport(reportId.value):await getLatestReport();if(token===loadVersion){reportData.value=report;reportId.value=report.id||''}}
 else if(active.value==='selections')selectionData.value=await getSelections({page:1,pageSize:50})
 else if(active.value==='collection'){Object.assign(aiConfig,await getAiConfig());collectionStatus.value=await getInsightCollection(day)}
 else if(active.value==='rules')Object.assign(ruleData,await getCurrentRule())
 syncUrl()
}catch(e:any){error.value=e.message}finally{if(token===loadVersion)loading.value=false}}
async function loadChart(){try{const c=currentChart.value;rankingData.value=c?.public?publicData.value[c.platform]:c?await getRankings(selectedChart.value,filters.date):{items:[]};syncUrl()}catch(e:any){error.value=e.message}}
function chooseChart(id:string){selectedChart.value=id;chartPlatform.value='';chartType.value='';loadChart()}
function filterCharts(){selectedChart.value=String(availableCharts.value[0]?.id||'');loadChart()}
function syncUrl(){const q=new URLSearchParams();Object.entries(filters).forEach(([k,v])=>v&&q.set(k,String(v)));if(active.value==='rankings'&&selectedChart.value)q.set('chart',selectedChart.value);if(active.value==='reports'&&reportId.value)q.set('reportId',reportId.value);history.replaceState(null,'',`#/${active.value}?${q}`)}
function nav(id:string){active.value=id;load()}
function addDays(day:string,offset:number){const d=new Date(`${day}T00:00:00Z`);d.setUTCDate(d.getUTCDate()+offset);return d.toISOString().slice(0,10)}
function shiftDate(offset:number){filters.date=addDays(filters.date,offset);filters.page=1;load()}
async function latestDate(){const c=await getCoverage('');filters.date=c.latestAvailableDate||c.date;load()}
function clear(){Object.assign(filters,{q:'',platform:'',region:'',poolState:'',selectionState:'',page:1});load()}
function changeState(state:string){filters.poolState=state;filters.page=1;load()}
function facts(row:any){try{return typeof row.frozen_facts==='string'?JSON.parse(row.frozen_facts):row.frozen_facts||{}}catch{return {}}}
function ranks(row:Product){const matches=row.rankings.filter(r=>(!filters.platform||r.platform===filters.platform)&&(!filters.region||r.region===filters.region));const observed=matches.filter(r=>r.rank!=null);return observed.length?observed:matches}
function rankText(r:Ranking){return r.rank!=null?`#${r.rank}`:stateLabel[r.dataState]||'—'}
function deltaText(r:Ranking){return r.delta7d===null?'—':r.delta7d>0?`↑ ${r.delta7d}`:r.delta7d<0?`↓ ${-r.delta7d}`:'持平'}
async function openDetail(p:{id:string}|string){try{const day=active.value==='reports'?(reportCoverage.value.asOfDate||addDays(String(reportData.value.periodEnd),-1)):filters.date;detail.value=await getProduct(typeof p==='string'?p:p.id,day);drawer.value=true}catch(e:any){ElMessage.error(e.message)}}
function openSelection(p:Product){selectionProduct.value=p;Object.assign(form,{owner:'',status:'SELECTED',referenceVersionId:undefined,selectedOn:filters.date,startedOn:'',finishedOn:'',note:''});selectionOpen.value=true}
async function selectReport(id:string){const p=await getProduct(id,reportCoverage.value.asOfDate||filters.date);openSelection({...p,selectionSummary:{total:0,inProgress:0,completed:0}})}
async function saveSelection(){if(!selectionProduct.value||!form.owner.trim()){ElMessage.warning('请填写负责人');return}try{await createSelection(selectionProduct.value.id,{...form,referenceVersionId:form.referenceVersionId||null,startedOn:form.startedOn||null,finishedOn:form.finishedOn||null});ElMessage.success('选用记录已保存');selectionOpen.value=false;await load()}catch(e:any){ElMessage.error(e.message)}}
async function saveAi(){try{Object.assign(aiConfig,await saveAiConfig({...aiConfig,apiKey:aiConfig.apiKey||undefined}),{apiKey:''});ElMessage.success('AI 配置已保存')}catch(e:any){ElMessage.error(e.message)}}
async function createWeeklyReport(){if(generating.value)return;generating.value=true;try{const day=new Date(`${filters.date}T00:00:00Z`).getUTCDay();reportData.value=await generateReport(addDays(filters.date,-((day+6)%7)),addDays(filters.date,1));reportId.value=reportData.value.id;auditPage.value=1;syncUrl();ElMessage.success(reportData.value.reused?'输入未变化，已复用原报告':'周报已生成，Skill与候选依据已冻结')}catch(e:any){ElMessage.error(e.message)}finally{generating.value=false}}
async function showHistory(){try{reportHistory.value=await getReportHistory(historyPage.value);historyOpen.value=true}catch(e:any){ElMessage.error(e.message)}}
async function chooseReport(id:string){try{reportData.value=await getReport(String(id));reportId.value=String(id);auditPage.value=1;historyOpen.value=false;syncUrl()}catch(e:any){ElMessage.error(e.message)}}
async function showSkill(){try{skillData.value=reportData.value.skillSnapshot||await getReportSkill();skillOpen.value=true}catch(e:any){ElMessage.error(e.message)}}
async function collectSources(){collecting.value=true;try{const result=await runInsightCollection();collectionStatus.value=await getInsightCollection(filters.date);ElMessage[result.attempts.some((a:any)=>a.status==='FAILED')?'warning':'success']('采集尝试已记录，请查看来源日期与结果')}catch(e:any){ElMessage.error(e.message)}finally{collecting.value=false}}
async function publishCurrentRule(){try{Object.assign(ruleData,await publishRule(ruleData.rulesJson));ElMessage.success('规则已发布为新版本')}catch(e:any){ElMessage.error(e.message)}}
function exportReport(){const r=reportData.value;if(r.researchSnapshot){const u=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=`研究周报-${r.id}.json`;a.click();URL.revokeObjectURL(u);return;}const text=`# 游戏研究周报 ${r.periodStart}—${r.periodEnd}\n\n报告 ${r.id} / 修订 ${r.revision}\n国内正式 ${r.domesticCount}，海外正式 ${r.overseasCount}，观察 ${r.observationCount}\n\n`+r.items.map((i:any)=>`## ${facts(i).productName}\n\n${i.content}\n\n来源：${facts(i).sourceUrl}\n证据：${i.evidence_refs}\n`).join('\n')+`\nSkill版本：${r.skillSnapshot?.version||'旧版'}\nSkill哈希：${r.skillSnapshot?.sha256||'无'}\n输入哈希：${r.inputSha256||'无'}\n覆盖：${JSON.stringify(reportCoverage.value)}\n`; const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`周报-${r.id}.md`;a.click();URL.revokeObjectURL(url)}
onMounted(()=>{const [path,query='']=location.hash.replace(/^#\//,'').split('?');if(menus.flatMap(m=>m.items).some(i=>i.id===path))active.value=path;new URLSearchParams(query).forEach((v,k)=>{if(k==='reportId')reportId.value=v;else if(k==='chart')selectedChart.value=v;else if(k in filters)(filters as any)[k]=k==='page'?Number(v):v});load()})
</script>
<template>
<div class="shell" :class="{'nav-collapsed':collapsed}">
<header><div class="brand"><span class="brand-symbol">◈</span> 锦鲤云</div><div class="top-nav"><span class="current">IAA 产品情报</span></div><div class="header-spacer"/><span class="header-status"><i/>公开数据验证中</span><button class="mobile-toggle" @click="collapsed=!collapsed" aria-label="切换侧栏"><el-icon><Fold/></el-icon></button></header>
<aside><div v-for="menu in menus" :key="menu.group" class="menu-group"><button class="menu-title" @click="groups[menu.group]=!groups[menu.group]" :aria-expanded="groups[menu.group]"><el-icon><component :is="menu.icon"/></el-icon><span>{{menu.group}}</span><el-icon class="group-arrow"><ArrowDown v-if="groups[menu.group]"/><ArrowRight v-else/></el-icon></button><template v-if="groups[menu.group]"><button v-for="item in menu.items" :key="item.id" :class="['menu-item',{active:active===item.id}]" :title="item.name" @click="nav(item.id)"><el-icon><component :is="item.icon"/></el-icon><span>{{item.name}}</span></button></template></div><div class="sidebar-footer">市场信号，沉淀产品机会<br><small>游探 · 实际数据独立留存</small></div></aside>
<main><div class="crumb">市场情报 / {{['collection','research','catalog','materials','planning'].includes(active)?'配置管理':'实际使用'}} / {{title}}</div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/>
<ResearchWorkspace v-if="researchModes.includes(active)" :key="active" :mode="active" :date="filters.date"/><section v-else-if="active==='overview'" class="page">
<div class="page-head"><div><h1>市场概览</h1><p>按指定业务日查看来源覆盖、热度信号和当前需要补证的地方。</p></div><span class="page-status">研究优先级 · 不代表收益预测</span></div>
<div class="date-toolbar"><span>数据日期</span><el-date-picker v-model="filters.date" type="date" value-format="YYYY-MM-DD" format="YYYY/MM/DD" :disabled-date="disabledDate" :clearable="false" @change="load"/><el-button @click="shiftDate(-1)">前一天</el-button><el-button :disabled="filters.date>=today()" @click="shiftDate(1)">后一天</el-button><button class="link" @click="latestDate">最新可用日期</button><span class="muted">缺失日不回填</span></div>
<div class="overview"><div><label>已观察产品</label><strong>{{stats.collected??'—'}}</strong><small>截至 {{filters.date}}</small></div><div><label>正式资格</label><strong>{{stats.formal??'—'}}</strong><small>版本级证据通过</small></div><div><label>待识别</label><strong>{{stats.pending??'—'}}</strong><small>需要身份或变现核验</small></div><div><label>来源状态</label><strong>{{coverage.coverageState||'—'}}</strong><small>{{coverage.charts?.length||0}} 个榜单定义</small></div></div>
<div class="data-panel insight-panel"><div class="section-heading"><h2>来源覆盖与研究边界</h2><button class="link" @click="nav('rankings')">查看榜单观察 →</button></div><p class="muted">热度榜、免费榜和买量来源分开记录；不同平台、国家和日期不综合排名。</p><el-table :data="coverage.charts||[]" size="small"><el-table-column label="平台 / 地区" min-width="150"><template #default="{row}">{{platformLabel[row.platform]||row.platform}} · {{regionLabel[row.region]||row.region}}</template></el-table-column><el-table-column prop="name" label="榜单" min-width="220"/><el-table-column label="状态" width="120"><template #default="{row}"><span :class="['status-tag',row.data_state==='COMPLETE'?'formal':'watch']">{{stateLabel[row.data_state]||row.data_state||'未采集'}}</span></template></el-table-column><el-table-column label="实际条数" width="100"><template #default="{row}">{{row.actual_count??'—'}}</template></el-table-column><el-table-column label="研究解释" min-width="260"><template #default="{row}">{{row.data_state==='MISSING_SNAPSHOT'?'来源缺失：不能当作榜外':row.completeness==='PARTIAL'?'部分覆盖：增长和持续性保持范围':'可用于同口径观察'}}</template></el-table-column></el-table></div>
<div class="workflow"><span>① 采集材料</span><i/><span>② 身份 / IAA / 玩法证据</span><i/><strong>③ 六维范围与分层推荐</strong><i/><span>④ 原型验证与反馈回收</span></div>
</section>
<section v-else-if="active==='products'" class="page">
<div class="page-head"><div><h1>产品库</h1><p>持续积累市场表现，追溯入选依据，记录产品选用情况。</p></div><span class="page-status">来源数据 · 资格待核验</span></div>
<div class="overview"><div><label>收录产品</label><strong>{{stats.collected??'—'}}</strong><small>截至 {{filters.date}} 已观察产品</small></div><div><label>正式入库</label><strong>{{stats.formal??'—'}}</strong><small>须有版本级 IAA 证据与规则命中</small></div><div><label>当日首次观察</label><strong>{{stats.firstObserved??'—'}}</strong><small>首次观察不等于新上线</small></div><div><label>选用记录</label><strong>{{stats.selections??'—'}}</strong><small>当前多人独立填报记录</small></div></div>
<div class="workflow"><span>① 榜单材料采集</span><i/><span>② 玩法与证据核验</span><i/><strong>③ 产品入库与挑选</strong><i/><span>④ 每周精选报告</span></div>
<div class="data-panel"><div class="state-tabs"><button v-for="tab in [['','全部'],['FORMAL','正式库'],['OBSERVING','观察中'],['PENDING_IDENTIFICATION','待识别']]" :key="tab[0]" :class="{active:filters.poolState===tab[0]}" @click="changeState(tab[0]!)">{{tab[1]}}<span v-if="tab[0]==='PENDING_IDENTIFICATION'"> · {{stats.pending??0}}</span></button></div>
<div class="date-toolbar"><span>数据日期</span><el-date-picker v-model="filters.date" type="date" value-format="YYYY-MM-DD" format="YYYY/MM/DD" :disabled-date="disabledDate" :clearable="false" @change="load"/><el-button @click="shiftDate(-1)">前一天</el-button><el-button :disabled="filters.date>=today()" @click="shiftDate(1)">后一天</el-button><button class="link" @click="latestDate">最新可用日期</button><span class="muted">榜单缺日不回填</span></div>
<form class="filterbar" @submit.prevent="filters.page=1;load()"><el-input v-model="filters.q" placeholder="产品名称" clearable/><el-select v-model="filters.platform" placeholder="全部平台" clearable><el-option v-for="(label,key) in platformLabel" :key="key" :label="label" :value="key"/></el-select><el-select v-model="filters.region" placeholder="全部地区" clearable><el-option v-for="(label,key) in regionLabel" :key="key" :label="label" :value="key"/></el-select><el-select v-model="filters.selectionState" placeholder="全部选用状态" clearable><el-option label="未选用" value="UNSELECTED"/><el-option label="已选" value="SELECTED"/><el-option label="制作中" value="IN_PROGRESS"/></el-select><el-button type="primary" native-type="submit">查询</el-button><el-button @click="clear">重置</el-button></form>
<div v-if="['WECHAT','DOUYIN'].includes(filters.platform)" class="source-note">小游戏公开页面缺少可核验的平台身份，目前保存在榜单观察中。<button class="link" @click="selectedChart='public-'+filters.platform;nav('rankings')">查看{{platformLabel[filters.platform]}}公开榜单 →</button></div><div class="table-caption"><span>共 {{data.total}} 款产品 · 数据日期：{{filters.date}}</span><span class="muted">不同平台、地区、榜单名次独立</span></div>
<div class="table-wrap"><el-table v-loading="loading" :data="data.items" row-key="id" border><el-table-column label="产品名称 / 核心玩法" min-width="245"><template #default="{row}"><div class="product-cell"><GameIcon :url="row.thumbnailUrl" :name="row.name"/><div><button class="link" @click="openDetail(row)">{{row.name}}</button><div class="muted">玩法待识别 · {{row.firstObservedDate?.slice(0,10)}}</div></div></div></template></el-table-column><el-table-column label="平台 / 地区" width="155"><template #default="{row}"><div v-for="r in ranks(row)" :key="`${r.versionId}-${r.chartId}`" class="rank-line">{{platformLabel[r.platform]}} {{regionLabel[r.region]}}</div></template></el-table-column><el-table-column label="入库状态" width="105"><template #default="{row}"><span :class="['status-tag',row.poolState==='FORMAL'?'formal':'watch']">{{stateLabel[row.poolState]}}</span></template></el-table-column><el-table-column label="热度排名" width="145"><template #default="{row}"><div v-for="r in ranks(row)" :key="`${r.versionId}-${r.chartId}`" class="rank-line" :title="r.chartName||''">{{rankText(r)}}</div></template></el-table-column><el-table-column label="7日变化" width="95"><template #default="{row}"><div v-for="r in ranks(row)" :key="`${r.versionId}-${r.chartId}`" class="rank-line" :class="r.delta7d!=null&&r.delta7d>0?'positive':'muted'" :title="r.delta7d===null?'缺少当日或D-7同榜快照':''">{{deltaText(r)}}</div></template></el-table-column><el-table-column label="市场信号 / 入选依据" min-width="260"><template #default="{row}"><div>已观察 · 待核验</div><div class="muted">{{ranks(row).filter(r=>r.rank!=null).length}} 个榜单有记录 · 变现证据未确认</div><div class="muted">其他缺失与覆盖详情可展开查看</div></template></el-table-column><el-table-column label="选用情况" width="105"><template #default="{row}">{{row.selectionSummary.total}} 人选用<div class="muted">{{row.selectionSummary.inProgress}} 制作中</div></template></el-table-column><el-table-column label="操作" width="115" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openDetail(row)">详情</el-button><el-button link type="primary" @click="openSelection(row)">选用</el-button></template></el-table-column><template #empty><div class="empty">该日期暂无匹配产品，不回填其他日期排名。</div></template></el-table></div><div class="pager"><span>每页 20 款</span><el-pagination v-model:current-page="filters.page" layout="prev,pager,next" :page-size="20" :total="data.total" @current-change="load"/></div></div></section>
<section v-else-if="active==='rankings'" class="page"><div class="page-head"><div><h1>榜单观察</h1><p>玩家热度与买量信号分别记录，不同平台、国家、榜单之间不直接比较名次。</p></div></div>
<div class="notice-band">国内：微信人气榜、抖音热门榜、iOS 免费榜。海外：Google Play 美英德法免费榜。</div><div class="data-panel"><div class="date-toolbar"><span>数据日期</span><el-date-picker v-model="filters.date" type="date" value-format="YYYY-MM-DD" :disabled-date="disabledDate" :clearable="false" @change="load"/><el-button @click="shiftDate(-1)">前一天</el-button><el-button :disabled="filters.date>=today()" @click="shiftDate(1)">后一天</el-button><button class="link" @click="latestDate">最新可用日期</button></div><div class="filterbar"><el-select v-model="chartPlatform" placeholder="全部平台" clearable @change="filterCharts"><el-option v-for="(label,key) in platformLabel" :key="key" :label="label" :value="key"/></el-select><el-select v-model="chartType" placeholder="全部榜单口径" clearable @change="filterCharts"><el-option label="人气 / 热门榜" value="POPULARITY"/><el-option label="免费榜" value="FREE"/></el-select><el-select v-model="selectedChart" class="chart-select" placeholder="请选择榜单" @change="loadChart"><el-option v-for="chart in availableCharts" :key="chart.id" :value="String(chart.id)" :label="`${regionLabel[chart.region]} · ${chart.name}`"/></el-select><el-button @click="load">刷新</el-button></div></div>
<div class="platform-tabs"><button v-for="p in [['public-WECHAT','微信 · 人气榜'],['public-DOUYIN','抖音 · 热门榜']]" :key="p[0]" :class="{active:selectedChart===p[0]}" @click="chooseChart(p[0]!)">{{p[1]}}<span>{{publicData[p[0]==='public-WECHAT'?'WECHAT':'DOUYIN']?.items?.length||0}} 条公开观察</span></button><button v-for="c in charts.filter(c=>!c.public)" :key="c.id" :class="{active:selectedChart===String(c.id)}" @click="chooseChart(String(c.id))">{{platformLabel[c.platform]}} {{regionLabel[c.region]}}<span>免费榜 · {{c.actual_count||0}} 条</span></button></div>
<div class="ranking-panel"><div class="section-heading"><h2>{{currentChart?.name||'暂无匹配榜单'}}</h2><span class="muted">{{filters.date}} · {{rankingData.items.length}} 条</span><a v-if="currentChart?.public" href="https://rank.gravity-engine.com/#/" target="_blank" rel="noopener noreferrer">查看来源 ↗</a></div><div v-if="currentChart?.public" class="source-note">引力引擎公开前20条 · 部分覆盖。名称、图标与发行方为来源页面显示值；缺少平台稳定身份，暂不进入产品库及正式精选。</div><div class="table-wrap"><el-table v-loading="loading" :data="rankingData.items" border><el-table-column label="平台 / 地区" width="155"><template #default>{{platformLabel[currentChart?.platform]}} {{regionLabel[currentChart?.region]}}</template></el-table-column><el-table-column label="产品" min-width="340"><template #default="{row}"><div class="product-cell"><GameIcon :url="row.thumbnail_url" :name="row.product_name"/><div><button v-if="row.product_id" class="link" @click="openDetail(String(row.product_id))">{{row.product_name}}</button><b v-else>{{row.product_name}}</b><div class="muted">{{row.developer||'平台独立版本'}}<span v-if="row.tags"> · {{row.tags.join(' / ')}}</span></div></div></div></template></el-table-column><el-table-column label="名次" width="90"><template #default="{row}"><span :class="['rank-number',{top:row.rank<=3}]">#{{row.rank}}</span></template></el-table-column><el-table-column label="来源日期" width="130"><template #default>{{filters.date}}</template></el-table-column><el-table-column label="覆盖状态" width="130"><template #default="{row}"><span :class="['status-tag',row.completeness==='COMPLETE'?'formal':'watch']">{{row.completeness==='COMPLETE'?'完整覆盖':'部分覆盖'}}</span></template></el-table-column><el-table-column label="来源 / 身份" min-width="210"><template #default="{row}">{{currentChart?.public?'引力引擎 · 身份待核验':currentChart?.platform==='IOS'?'Apple 游戏分类 RSS':'AppBrain · Google Play'}}<div class="muted">{{row.snapshot_id?`快照 ${row.snapshot_id}`:'公开页面观察，不是正式入库'}}</div></template></el-table-column><template #empty><div class="empty">该日期暂无快照，不回填其它日期数据。</div></template></el-table></div></div></section>
<section v-else-if="active==='reports'" class="page">
<div class="page-head"><div><h1>每周精选</h1><p>{{reportData.periodStart}} — {{reportData.periodEnd}}（不含结束日） · 修订 {{reportData.revision||'—'}} · 生成于 {{generatedTime}}</p></div><div class="head-actions"><el-button @click="showHistory">历史周报</el-button><el-button @click="showSkill">精选 Skill</el-button><el-button :disabled="!reportData.id" @click="exportReport">导出周报</el-button></div></div>
<div class="report-generation"><span>分析截止日</span><el-date-picker v-model="filters.date" type="date" value-format="YYYY-MM-DD" :clearable="false" :disabled-date="disabledDate"/><el-button type="primary" :loading="generating" @click="createWeeklyReport">生成本周精选</el-button><span class="muted">从本周一到截止日；相同输入复用，变化后新增修订。</span></div>
<div class="notice-band">{{reportData.skillSnapshot?'按冻结方案目标数量，不足不凑数':'历史报告保留冻结内容'}} · 当前 {{reportData.items.length}} 款 · 正式IAA {{(reportData.domesticCount||0)+(reportData.overseasCount||0)}} · 市场观察 {{reportData.observationCount||0}}。热度不等于增长，研究优先级不等于盈利概率。</div>
<details v-if="reportData.id" class="insight-panel"><summary>数据覆盖与筛选依据 · {{reportData.skillSnapshot?.version||'历史规则'}}</summary><p>{{reportCoverage.policy}}</p><p>{{reportCoverage.shortfallReason}}</p><el-table :data="reportCoverage.sources||[]" size="small"><el-table-column label="来源 / 榜单" min-width="240"><template #default="{row}">{{row.source_name}} · {{row.name}}</template></el-table-column><el-table-column label="近14日覆盖" width="130"><template #default="{row}">{{row.observedDays??row.observed_days}} / {{row.windowDays||'—'}}</template></el-table-column><el-table-column label="7日对比条件" width="140"><template #default="{row}">{{row.delta7dReady?'两端快照齐全':'缺少对比快照'}}</template></el-table-column><el-table-column label="缺失日期" min-width="200"><template #default="{row}">{{row.missingDates?.join('、')||'—'}}</template></el-table-column></el-table><p v-for="p in reportCoverage.publicObservations||[]" :key="p.platform">{{platformLabel[p.platform]}}：{{p.actual_count}} 条公开观察，{{p.reason}}</p><p>{{reportCoverage.historyNotice}}</p></details>
<div class="report-tabs state-tabs"><button v-for="t in [['ALL','全部候选'],['DOMESTIC','国内'],['OVERSEAS','海外']]" :key="t[0]" :class="{active:reportGroup===t[0]}" @click="reportGroup=t[0]!">{{t[1]}}</button></div><div v-if="reportData.message" class="empty">{{reportData.message}}</div><div v-else-if="!visibleReports.length" class="empty">本期没有符合当前筛选条件的候选；缺数据不等于没有机会。</div><div v-else class="report-grid"><ReportCard v-for="row in visibleReports" :key="row.id" :row="row" @detail="id=>openDetail(String(id))" @select="id=>selectReport(String(id))"/></div>
<div v-if="reportData.researchSnapshot" class="insight-panel"><h3>本期诊断与补证 · 全候选保留</h3><p>{{reportData.researchSnapshot.result.diagnostic}}</p><p>可用材料截止（UTC）：{{reportData.availableCutoff}} · 规则结果已冻结；AI未调用。</p><el-table :data="(reportData.researchSnapshot.result.rows||[]).slice((auditPage-1)*20,auditPage*20)" border><el-table-column prop="name" label="候选" min-width="180"/><el-table-column label="层级" width="110"><template #default="{row}">{{({ready:'重点验证',conditional:'条件推荐',lead:'线索推荐',paused:'暂缓验证',excluded:'范围不匹配'} as any)[row.route]}}</template></el-table-column><el-table-column label="范围 / 覆盖" width="160"><template #default="{row}">{{row.utilityRange.lower.toFixed(1)}}～{{row.utilityRange.upper.toFixed(1)}}<div class="muted">输入覆盖 {{(row.inputCoverage*100).toFixed(1)}}%</div></template></el-table-column><el-table-column label="行动与缺口" min-width="300"><template #default="{row}">{{row.action}}<div class="muted">{{row.unselectedReason||row.slot}}</div><details><summary>补证与逐维依据</summary><p v-for="t in row.evidenceTasks" :key="t.key">{{t.label}} · {{t.impact===null?'前提优先':`最多缩小 ${t.impact.toFixed(2)} 分`}}</p><p v-for="r in row.dimensions" :key="r.key">{{r.key}}：{{r.lower.toFixed(2)}}～{{r.upper.toFixed(2)}} · {{r.status}} · {{r.boundMethod}}</p></details></template></el-table-column><el-table-column label="产品" width="90"><template #default="{row}"><el-button link @click="openDetail(String(row.productId))">详情</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="auditPage" :page-size="20" :total="reportData.researchSnapshot.result.rows.length" layout="prev,pager,next"/></div>
<details v-if="reportData.candidateAudit&&!reportData.researchSnapshot" class="insight-panel"><summary>本期候选审计 · {{reportData.candidateAudit.length}} 条平台地区记录（含去重与淘汰）</summary><el-table :data="auditRows" size="small"><el-table-column prop="product_name" label="产品" min-width="180"/><el-table-column label="平台 / 地区" width="150"><template #default="{row}">{{platformLabel[row.platform]}} / {{row.region}}</template></el-table-column><el-table-column label="研究范围" width="100"><template #default="{row}">{{row.v22?`${Number(row.v22.utilityRange.lower).toFixed(1)}～${Number(row.v22.utilityRange.upper).toFixed(1)}`:'历史记录'}}</template></el-table-column><el-table-column label="结论" min-width="160"><template #default="{row}">{{row.v22?.unselectedReason||row.v22?.action||decisionLabel[row.decision]||row.decision}}</template></el-table-column></el-table><el-pagination v-model:current-page="auditPage" :page-size="20" :total="reportData.candidateAudit.length" layout="prev, pager, next"/></details>
<el-drawer v-model="historyOpen" title="历史周报 · 所有修订" size="min(850px, 96vw)"><el-table :data="reportHistory.items"><el-table-column label="报告期" min-width="220"><template #default="{row}">{{row.period_start}} — {{row.period_end}}</template></el-table-column><el-table-column prop="revision" label="修订" width="65"/><el-table-column prop="item_count" label="款数" width="65"/><el-table-column label="查看" width="90"><template #default="{row}"><el-button link type="primary" @click="chooseReport(row.id)">查看</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="historyPage" :page-size="20" :total="reportHistory.total" layout="prev, pager, next" @current-change="showHistory"/></el-drawer>
<el-drawer v-model="skillOpen" title="精选 Skill · 冻结版本" size="min(850px, 96vw)"><p>当前{{reportData.skillSnapshot?'报告生成时保存':'系统默认'}}版本：{{skillData?.version}}</p><p class="muted">Java执行确定性模型；AI未参与本期结论生成。后续变更不会覆盖旧报告。</p><pre class="skill-text">{{skillData?.instructions}}</pre><pre class="skill-text">{{JSON.stringify(skillData?.policy,null,2)}}</pre><p class="hash-text">SHA256：{{skillData?.sha256}}</p></el-drawer>
</section>
<section v-else-if="active==='selections'" class="page"><div class="page-head"><div><h1>选用记录</h1><p>多人记录独立维护，展示当前制作状态。</p></div><el-button type="primary" @click="nav('products')">从产品库新增</el-button></div><div class="table-wrap"><el-table :data="selectionData.items" border><el-table-column prop="id" label="记录ID" width="90"/><el-table-column prop="product_name" label="产品"/><el-table-column prop="owner_name" label="负责人"/><el-table-column prop="status" label="状态"/><el-table-column prop="selected_on" label="选用日期"/><el-table-column prop="note" label="备注"/></el-table></div></section>
<section v-else-if="active==='collection'" class="page"><div class="page-head"><div><h1>AI 采集中心</h1><p>配置任意 OpenAI-compatible 中转；API Key 只写入服务端加密字段，读取时不回显。</p></div><el-tag :type="aiConfig.apiKeyConfigured?'success':'warning'">{{aiConfig.apiKeyConfigured?'密钥已配置':'未配置密钥'}}</el-tag></div><div class="insight-panel" v-if="collectionStatus"><div class="section-heading"><h2>市场数据积累</h2><el-button :loading="collecting" @click="collectSources">采集可用免费来源</el-button></div><p>每日采集：{{collectionStatus.dailyEnabled?'已启用（中国时间08:00）':'未启用'}} · 每周留档：{{collectionStatus.weeklyEnabled?'已启用（周一09:00）':'未启用'}} · AppBrain自动取材：{{collectionStatus.appBrainEnabled?'启用':'未启用，需网络可达后配置'}}</p><p class="muted">微信/抖音目前仍需公开渲染材料导入；不声称全平台自动采集。</p><el-table :data="collectionStatus.sources" size="small"><el-table-column prop="name" label="榜单" min-width="200"/><el-table-column label="观察窗来源覆盖" width="160"><template #default="{row}">{{row.observedDays}} / {{row.windowDays||14}}</template></el-table-column><el-table-column prop="currentState" label="所选日期状态" min-width="160"/></el-table><el-table :data="collectionStatus.attempts" size="small" max-height="260"><el-table-column prop="source_key" label="任务"/><el-table-column prop="requested_date" label="尝试日期"/><el-table-column prop="status" label="结果"/><el-table-column prop="result_json" label="结果依据 / 缺口" min-width="260" show-overflow-tooltip/></el-table></div><div class="config-card"><el-form label-width="125px"><el-form-item label="供应商名称"><el-input v-model="aiConfig.providerName" placeholder="例如 Grok / DeepSeek / 公司中转"/></el-form-item><el-form-item label="Base URL"><el-input v-model="aiConfig.baseUrl" placeholder="https://your-proxy.example.com/v1"/></el-form-item><el-form-item label="模型"><el-input v-model="aiConfig.model" placeholder="例如 gpt-4o-mini / deepseek-chat"/></el-form-item><el-form-item label="API Key"><el-input v-model="aiConfig.apiKey" type="password" show-password placeholder="留空表示保持当前密钥"/></el-form-item><el-form-item label="超时（秒）"><el-input-number v-model="aiConfig.timeoutSeconds" :min="5" :max="300"/></el-form-item><el-form-item label="Temperature"><el-input-number v-model="aiConfig.temperature" :min="0" :max="2" :step="0.1"/></el-form-item><el-form-item label="启用"><el-switch v-model="aiConfig.enabled"/></el-form-item><el-button type="primary" @click="saveAi">保存配置</el-button></el-form><div class="config-help"><b>配置格式</b><p>只要中转兼容 <code>/v1/chat/completions</code>，填写 Base URL、模型和 Key 即可。Grok、GPT、DeepSeek 都走同一套字段。</p><p>当前配置可保存，模型调用链尚未验收；候选数字与资格由 Java 校验。</p></div></div></section>
<section v-else-if="active==='rules'" class="page"><div class="page-head"><div><h1>规则配置</h1><p>规则发布会产生新版本；历史周报和旧规则命中不会被覆盖。</p></div><el-tag type="info">当前 v{{ruleData.versionNumber || '—'}}</el-tag></div><div class="config-card"><el-input v-model="ruleData.rulesJson" type="textarea" :rows="16"/><div class="config-help"><p>建议字段：<code>topN</code>、<code>windowDays</code>、<code>sustainedDays</code>、<code>rapidRiseDays</code>、<code>rapidRiseDelta</code>、<code>reportDomesticLimit</code>、<code>reportOverseasLimit</code>。</p><p>当前支持规则版本保存与发布；规则试算及自动市场判定尚未完成。</p></div><el-button type="primary" @click="publishCurrentRule">发布新规则版本</el-button></div></section>
<footer>游探 · Java + MySQL · 名次按来源独立，缺失不回填</footer></main><el-drawer v-model="drawer" :title="detail?.name || '产品详情'" size="540px"><template v-if="detail"><div class="drawer-meta"><el-tag>{{stateLabel[detail.poolState]||detail.poolState}}</el-tag><span>截至 {{detail.date}}</span></div><h3>平台版本与榜单</h3><div v-for="r in detail.rankings" :key="`${r.versionId}-${r.chartId}`" class="detail-rank"><div><b>{{platformLabel[r.platform]||r.platform}}</b> <span class="muted">{{r.versionName}} · 版本ID {{r.versionId}}</span></div><div>{{r.chartName}} <strong v-if="r.rank">#{{r.rank}}</strong><span v-else>{{stateLabel[r.dataState]||r.dataState}}</span><span v-if="r.delta7d!==null" class="delta">7日 {{r.delta7d>0?'+':''}}{{r.delta7d}}</span></div><div class="muted">变现：{{r.monetization}} · {{r.dataState}}</div></div><h3>当前选用记录</h3><div v-if="!detail.selections?.length" class="muted">暂无选用记录</div><div v-for="s in detail.selections" :key="s.id" class="selection-row"><b>{{s.owner_name}}</b><el-tag size="small">{{s.status}}</el-tag><span>{{s.selected_on}}</span></div><el-button type="primary" class="drawer-action" @click="openSelection({id:detail.id,name:detail.name,poolState:detail.poolState,firstObservedDate:detail.firstObservedDate,stateAsOf:detail.date,rankings:detail.rankings,selectionSummary:{total:detail.selections.length,inProgress:0,completed:0}})">新增选用</el-button></template></el-drawer>
<el-dialog v-model="selectionOpen" title="新增选用记录" width="480px"><el-form label-width="90px"><el-form-item label="负责人" required><el-input v-model="form.owner" maxlength="40"/></el-form-item><el-form-item label="参考版本"><el-select v-model="form.referenceVersionId" clearable placeholder="可选"><el-option v-for="r in versionChoices" :key="r.versionId" :label="`${platformLabel[r.platform]||r.platform} · ${r.versionName}`" :value="r.versionId"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="已选" value="SELECTED"/><el-option label="制作中" value="IN_PROGRESS"/><el-option label="已完成" value="COMPLETED"/><el-option label="放弃" value="ABANDONED"/></el-select></el-form-item><el-form-item label="选用日期"><el-date-picker v-model="form.selectedOn" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="备注"><el-input v-model="form.note" type="textarea" maxlength="1000" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="selectionOpen=false">取消</el-button><el-button type="primary" @click="saveSelection">保存</el-button></template></el-dialog>
</div>
</template>

